.checkbox-label {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 8px;
  cursor: pointer;
}

.checkbox-input {
  /* Visually hidden but still accessible */
  position: absolute;
  opacity: 0;
