## How to Apply This Pattern

### React Implementation Example

```tsx
import { useEffect, useRef, useState } from 'react';

// Skip link component based on the documented pattern
export function SkipLink({ targetId }: { targetId: string }) {
  const handleSkip = (e: React.MouseEvent) => {
    e.preventDefault();
    const target = document.getElementById(targetId);
    if (target) {
      target.focus();
      target.scrollIntoView();
    }
  };

  return (
    <a
      href={`#${targetId}`}
      className="skip-link"
      onClick={handleSkip}
    >
      Skip to main content
    </a>
  );
}

// Accessible modal with focus management
export function AccessibleModal({
  isOpen,
  onClose,
  title,
  children
}: {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}) {
  const modalRef = useRef<HTMLDivElement>(null);
  const previousFocusRef = useRef<HTMLElement | null>(null);
  const [focusTrapActive, setFocusTrapActive] = useState(false);

  // Store element that triggered modal
  useEffect(() => {
    if (isOpen) {
      previousFocusRef.current = document.activeElement as HTMLElement;
      setFocusTrapActive(true);
    }
  }, [isOpen]);

  // Move focus to modal when opened
  useEffect(() => {
    if (isOpen && modalRef.current) {
      // Focus first focusable element in modal
      const firstFocusable = modalRef.current.querySelector<HTMLElement>(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      );
      firstFocusable?.focus();
    }
  }, [isOpen]);

  // Return focus when closed
  useEffect(() => {
    if (!isOpen && previousFocusRef.current) {
      previousFocusRef.current.focus();
      setFocusTrapActive(false);
    }
  }, [isOpen]);

  // Keyboard handlers
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      // Escape to close
      if (e.key === 'Escape') {
        onClose();
        return;
      }

      // Focus trap: Tab cycling
      if (e.key === 'Tab' && modalRef.current) {
        const focusableElements = modalRef.current.querySelectorAll<HTMLElement>(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );

        if (focusableElements.length === 0) return;

        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];

        // Shift+Tab on first element → go to last
        if (e.shiftKey && document.activeElement === firstElement) {
          e.preventDefault();
          lastElement.focus();
        }
        // Tab on last element → go to first
        else if (!e.shiftKey && document.activeElement === lastElement) {
          e.preventDefault();
          firstElement.focus();
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <>
      {/* Backdrop */}
      <div
        className="modal-backdrop"
        onClick={onClose}
        aria-hidden="true"
      />

      {/* Modal */}
      <div
        ref={modalRef}
        className="modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
      >
        <div className="modal-header">
          <h2 id="modal-title">{title}</h2>
          <button
            onClick={onClose}
            className="modal-close"
            aria-label="Close dialog"
          >
            ✕
          </button>
        </div>

        <div className="modal-content">
          {children}
        </div>

        <div className="modal-footer">
          <button onClick={onClose} className="button-secondary">
            Cancel
          </button>
          <button className="button-primary">
            Confirm
          </button>
        </div>
      </div>
    </>
  );
}

// Accessible button with proper focus indicator
export function AccessibleButton({
  children,
  onClick,
  variant = 'primary',
  disabled = false,
  ariaLabel
}: {
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary';
  disabled?: boolean;
  ariaLabel?: string;
}) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className={`accessible-button ${variant}`}
      aria-label={ariaLabel}
      // Proper button semantics (automatically keyboard accessible)
    >
      {children}
    </button>
  );
}

// Keyboard-navigable menu based on the documented pattern
export function KeyboardNavigableMenu({ items }: {
  items: Array<{ label: string; href: string }>
}) {
  const [activeIndex, setActiveIndex] = useState(-1);
  const menuRef = useRef<HTMLUListElement>(null);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActiveIndex(prev => (prev + 1) % items.length);
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActiveIndex(prev => (prev - 1 + items.length) % items.length);
        break;
      case 'Home':
        e.preventDefault();
        setActiveIndex(0);
        break;
      case 'End':
        e.preventDefault();
        setActiveIndex(items.length - 1);
        break;
    }
  };

  // Focus active item when index changes
  useEffect(() => {
    if (activeIndex >= 0 && menuRef.current) {
      const activeLink = menuRef.current.children[activeIndex]?.querySelector('a');
      activeLink?.focus();
    }
  }, [activeIndex]);

  return (
    <nav aria-label="Main navigation">
      <ul
        ref={menuRef}
        className="keyboard-menu"
        role="menu"
        onKeyDown={handleKeyDown}
      >
        {items.map((item, index) => (
          <li key={index} role="none">
            <a
              href={item.href}
              role="menuitem"
              className={index === activeIndex ? 'active' : ''}
            >
              {item.label}
            </a>
          </li>
        ))}
      </ul>
    </nav>
  );
}
```

