## How to Apply This Pattern

### React Implementation Example

```tsx
import { useState, useEffect, useRef } from 'react';

interface UndoToastProps {
  message: string;
  duration?: number;
  onUndo: () => void;
  onComplete: () => void;
}

export function UndoToast({
  message,
  duration = 5000,
  onUndo,
  onComplete
}: UndoToastProps) {
  const [isVisible, setIsVisible] = useState(true);
  const [timeRemaining, setTimeRemaining] = useState(duration);
  const timerRef = useRef<NodeJS.Timeout | null>(null);
  const startTimeRef = useRef<number>(Date.now());

  useEffect(() => {
    // Update time remaining every 100ms for smooth progress bar
    const progressInterval = setInterval(() => {
      const elapsed = Date.now() - startTimeRef.current;
      const remaining = Math.max(0, duration - elapsed);
      setTimeRemaining(remaining);

      if (remaining === 0) {
        clearInterval(progressInterval);
        setIsVisible(false);
        onComplete();
      }
    }, 100);

    return () => {
      clearInterval(progressInterval);
      if (timerRef.current) {
        clearTimeout(timerRef.current);
      }
    };
  }, [duration, onComplete]);

  const handleUndo = () => {
    setIsVisible(false);
    onUndo();

    // Announce to screen readers
    const announcement = document.createElement('div');
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.textContent = 'Action undone';
    document.body.appendChild(announcement);
    setTimeout(() => document.body.removeChild(announcement), 1000);
  };

  const progress = (timeRemaining / duration) * 100;

  if (!isVisible) return null;

  return (
    <div
      className="undo-toast"
      role="status"
      aria-live="polite"
      aria-atomic="true"
    >
      <div className="undo-toast-content">
        <span className="undo-toast-message">{message}</span>
        <button
          onClick={handleUndo}
          className="undo-button"
          aria-label="Undo action"
        >
          Undo
        </button>
      </div>

      {/* Visual progress indicator */}
      <div
        className="undo-toast-progress"
        style={{ width: `${progress}%` }}
        role="progressbar"
        aria-valuenow={Math.round(progress)}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label="Time remaining to undo"
      />
    </div>
  );
}

// Example usage: Email send with undo
export function EmailComposer() {
  const [isSending, setIsSending] = useState(false);
  const [showUndo, setShowUndo] = useState(false);
  const [email, setEmail] = useState({ to: '', subject: '', body: '' });
  const pendingEmailRef = useRef<typeof email | null>(null);

  const handleSend = () => {
    // Store email for potential undo
    pendingEmailRef.current = { ...email };

    // Show undo toast
    setShowUndo(true);
    setIsSending(true);
  };

  const handleUndo = () => {
    // Cancel send
    setShowUndo(false);
    setIsSending(false);
    pendingEmailRef.current = null;

    // Keep email in composer
    console.log('Send cancelled');
  };

  const handleComplete = async () => {
    // Actually send the email after delay
    if (pendingEmailRef.current) {
      try {
        await sendEmail(pendingEmailRef.current);
        console.log('Email sent successfully');

        // Clear composer
        setEmail({ to: '', subject: '', body: '' });
        pendingEmailRef.current = null;
      } catch (error) {
        console.error('Failed to send email:', error);
      } finally {
        setIsSending(false);
        setShowUndo(false);
      }
    }
  };

  return (
    <div className="email-composer">
      <input
        type="email"
        placeholder="To"
        value={email.to}
        onChange={(e) => setEmail({ ...email, to: e.target.value })}
        disabled={isSending}
      />
      <input
        type="text"
        placeholder="Subject"
        value={email.subject}
        onChange={(e) => setEmail({ ...email, subject: e.target.value })}
        disabled={isSending}
      />
      <textarea
        placeholder="Message"
        value={email.body}
        onChange={(e) => setEmail({ ...email, body: e.target.value })}
        disabled={isSending}
      />

      <button
        onClick={handleSend}
        disabled={isSending || !email.to || !email.body}
        className="send-button"
      >
        {isSending ? 'Sending...' : 'Send'}
      </button>

      {showUndo && (
        <UndoToast
          message="Email sent"
          duration={5000}
          onUndo={handleUndo}
          onComplete={handleComplete}
        />
      )}
    </div>
  );
}

async function sendEmail(email: any): Promise<void> {
  // Actual email sending logic
  return new Promise((resolve) => setTimeout(resolve, 1000));
}
```

